selector_to_html = {"a[href=\"#module-pyskyfire.regen.outer_wall\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.outer_wall<a class=\"headerlink\" href=\"#module-pyskyfire.regen.outer_wall\" title=\"Link to this heading\">\u00b6</a></h1><p>The cold-side envelope of a cooling circuit, read like a contour.</p><p><a class=\"reference internal\" href=\"../contour/Contour.html#pyskyfire.regen.contour.Contour\" title=\"pyskyfire.regen.contour.Contour\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Contour</span></code></a> describes where the hot gas sees the\nchamber. This describes the other face of the same hardware: the outermost\nsurface the cooling channels and their walls reach. It is what a manifold\nwrapped around the chamber has to sit against, and it is stated the same way \u2013\na radius as a function of axial station, plus the direction the wall faces\nthere \u2013 so the two can be read side by side.</p>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"../contour/Contour.html#pyskyfire.regen.contour.Contour\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.contour.Contour\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.contour.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Contour</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chamber_angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nozzle_angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Inner hot-gas contour of a bell-type rocket engine.</p><p>Represents the geometric wall line from the start of the chamber to\nthe nozzle exit, providing local areas, slopes, and radii.</p><p class=\"rubric\">Notes</p><p>This class is used by higher-level objects such as\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">CoolingCircuit</span></code> and\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">ThrustChamber</span></code>.</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.regen.outer_wall.OUTER_WALL_KINDS\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OUTER_WALL_KINDS\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.outer_wall.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OUTER_WALL_KINDS</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">('envelope',</span> <span class=\"pre\">'equivalent')</span></span></dt><dd></dd>", "a[href=\"OuterWall.html#pyskyfire.regen.outer_wall.OuterWall\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.outer_wall.OuterWall\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.outer_wall.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OuterWall</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">xs</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">envelope</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">equivalent</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Outer radius of a channelled wall against axial station.</p><p class=\"rubric\">Notes</p><p>Build one with <a class=\"reference internal\" href=\"#pyskyfire.regen.outer_wall.OuterWall.from_circuit\" title=\"pyskyfire.regen.outer_wall.OuterWall.from_circuit\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_circuit()</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.regen.outer_wall.OuterWall.from_chamber\" title=\"pyskyfire.regen.outer_wall.OuterWall.from_chamber\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_chamber()</span></code></a> rather than\ndirectly, unless the wall is being stated by hand for a part pyskyfire did\nnot resolve.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
